#!/bin/bash
# Generated by scripts/scb_to_harbor.py for step checkpoint_2 of circuit_eval.
# Do not edit by hand — re-run the converter instead.

set +e

export TERM="${TERM:-xterm}"
export COLUMNS="${COLUMNS:-240}"
export LINES="${LINES:-60}"
PYTEST_TMP_ROOT=/tmp/scb-pytest-checkpoint_2
rm -rf "$PYTEST_TMP_ROOT"
mkdir -p "$PYTEST_TMP_ROOT"
# Harbor reuses this container for the next agent step, so on exit drop
# the held-out tests and per-step reports before the agent can read them.
# /tmp/scb-check-history.jsonl must survive: the shim diffs against it.
cleanup_verifier_state() {
  find /tests -mindepth 1 -delete
  rm -rf /tmp/ctrf.json /tmp/pytest-report.json /tmp/scb-check-report.json \
    /tmp/scb-check.stderr "$PYTEST_TMP_ROOT"
}
trap cleanup_verifier_state EXIT

if [ -d /assets ] && find /assets -mindepth 1 -print -quit | grep -q .; then
  mkdir -p /tests/assets
  cp -a /assets/. /tests/assets/
fi

PYTEST_USER_PREFIX=()
if [ "$(id -u)" = "0" ] && id agent >/dev/null 2>&1; then
  chown -R agent:agent /app /tests /logs/verifier /tmp/uv-cache /tmp/pip-cache /tmp/agent_home "$PYTEST_TMP_ROOT" 2>/dev/null || true
  PYTEST_USER_PREFIX=(runuser -u agent --)
fi

INCLUDE_PRIOR=true
PRIOR_TESTS=()
if [ "$INCLUDE_PRIOR" = "true" ]; then
  PRIOR_TESTS=(/tests/test_checkpoint_1.py)
fi

"${PYTEST_USER_PREFIX[@]}" uv run \
  --with pytest==9.0.3 \
  --with pytest-json-ctrf==0.4.1 \
  --with pytest-json-report==1.5.0 \
  --with pytest-timeout==2.4.0 \
  --with pyyaml \
  -m pytest \
    --timeout=30.0 \
    --timeout-method=signal \
    --basetemp="$PYTEST_TMP_ROOT" \
    "${PRIOR_TESTS[@]}" \
    /tests/test_checkpoint_2.py \
    --checkpoint "checkpoint_2" \
    --entrypoint "uv run --project /app circopt.py" \
    --ctrf=/tmp/ctrf.json \
    --json-report \
    --json-report-file=/tmp/pytest-report.json \
    --json-report-omit=traceback,streams,log,collectors,warnings \
    -rA
PYTEST_RC=$?

# Measure verbosity and erosion on the post-edit /app snapshot via
# the image's pinned scb-check. Failures here never abort the step: the
# scores are diagnostic and the shim treats a missing report as 'no
# scb-check data'.
SCB_CHECK_REPORT=/tmp/scb-check-report.json
rm -f "$SCB_CHECK_REPORT"
"${PYTEST_USER_PREFIX[@]}" env PATH="/opt/uv-tools/scb-check/bin:$PATH" \
  scb-check check /app --report --include-all \
  >"$SCB_CHECK_REPORT" 2>/tmp/scb-check.stderr
SCB_CHECK_RC=$?
if [ "$SCB_CHECK_RC" -ne 0 ]; then
  echo "[scb-check] exited rc=$SCB_CHECK_RC (see /tmp/scb-check.stderr)" >&2
fi

python3 /tests/_ctrf_to_reward.py \
  --ctrf /tmp/ctrf.json \
  --pytest-report /tmp/pytest-report.json \
  --current-checkpoint "checkpoint_2" \
  --pytest-rc "$PYTEST_RC" \
  --scb-check-report "$SCB_CHECK_REPORT" \
  --scb-check-rc "$SCB_CHECK_RC" \
  --scb-check-history /tmp/scb-check-history.jsonl \
  --out-dir /logs/verifier
